content = movie_note['content']
fincher_movies = []

# Split content into lines and process each line
lines = content.split('\n')
for line in lines:
    line = line.strip()
    # Check if this line contains the director information
    if line.startswith(' - ') and 'director: David Fincher' in line:
        # The movie title is the line before this one
        # Find the previous non-empty line that is not a header
        prev_line = None
        for i in range(len(lines) - 1, -1, -1):
            if i < len(lines) - 1:
                prev_line = lines[i].strip()
                if prev_line and not prev_line.startswith('#') and not prev_line.startswith(' - '):
                    break
        if prev_line and not prev_line.startswith('#'):
            movie_title = prev_line
            if movie_title not in fincher_movies:
                fincher_movies.append(movie_title)

# If still empty, try a simpler approach - look for any line with "director: David Fincher"
if not fincher_movies:
    for line in lines:
        line = line.strip()
        if line.startswith(' - ') and 'director: David Fincher' in line:
            # Extract the movie title which is the text before the director line
            movie_title = line.split(' - ')[0]
            if movie_title not in fincher_movies:
                fincher_movies.append(movie_title)

print(f"David Fincher movies: {fincher_movies}")
```

