# Final verification that the mapping matches private_data expectations
final_mapping = {}
for contact in coworker_contacts:
    contact_name = contact['first_name']
    if contact_name in shares:
        final_mapping[contact['email']] = shares[contact_name]
    else:
        final_mapping[contact['email']] = 0

# Verify keys match contact list
assert set(final_mapping.keys()) == set([contact['email'] for contact in coworker_contacts]), "Email keys don't match contact list"

# Verify shares are zero for contacts not in note
for contact in coworker_contacts:
    contact_name = contact['first_name']
    if contact_name not in shares:
        assert final_mapping[contact['email']] == 0, f"Contact {contact_name} not in note should have zero share but has {final_mapping[contact['email']]}"

# Verify shares for contacts in note are correct
for contact in coworker_contacts:
    contact_name = contact['first_name']
    if contact_name in shares:
        assert final_mapping[contact['email']] == shares[contact_name], f"Share for {contact_name} should be {shares[contact_name]} but is {final_mapping[contact['email']]}"

print("Final verification successful: mapping matches private_data expectations")
