# Parse the dinner share note to extract shares
shares = {}
lines = dinner_share_note['content'].split('\n')
for line in lines:
    line = line.strip()
    if line.startswith('-'):
        parts = line.split('=>')
        if len(parts) == 2:
            name = parts[0].strip()
            amount = float(parts[1].strip().replace('$', ''))
            shares[name.strip('-')] = amount

# Create cleaned versions of names (remove hyphens, standardize capitalization)
note_coworkers_clean = {name.strip('-').strip() for name in shares.keys()}
contact_coworkers_clean = {contact['first_name'].strip().strip('-') for contact in coworker_contacts}

# Find the intersection of cleaned names to identify common coworkers
common_coworkers = note_coworkers_clean.intersection(contact_coworkers_clean)

# Create a mapping from contact names to their shares (zero for those not in the note or with zero shares)
user_email_to_share = {}
for contact in coworker_contacts:
    contact_name = contact['first_name'].strip().strip('-')
    if contact_name in shares:
        user_email_to_share[contact['email']] = shares[contact_name]
    else:
        user_email_to_share[contact['email']] = 0

print(f"Common coworkers: {common_coworkers}")
print(f"Final user_email_to_share mapping: {user_email_to_share}")
```

