def extract_total_amount(content):
    """Extract total amount from bill content using regex patterns"""
    import re
    lines = content['content'].split('\n')
    total_amount = None

    for line in lines:
        line = line.strip()
        # Look for patterns like "Total => $X.XX", "Total Amount => $X.XX", or "Base Charge => $X.XX"
        if "Total" in line or "Base Charge" in line:
            # First try "Total => $X.XX" or "Total Amount => $X.XX"
            if "Total" in line:
                # Extract amount after "Total => $" or "Total Amount => $"
                amount_match = re.search(r'Total\s*=>\s*\$([0-9,]+)', line)
                if amount_match:
                    amount_str = amount_match.group(1)
                else:
                    amount_match = re.search(r'Total\s*Amount\s*=>\s*\$([0-9,]+)', line)
                    if amount_match:
                        amount_str = amount_match.group(1)
                    else:
                        continue
            else:
                # For Base Charge, look for "Base Charge => $X.XX"
                amount_match = re.search(r'Base Charge\s*=>\s*\$([0-9,]+)', line)
                if amount_match:
                    amount_str = amount_match.group(1)
                else:
                    continue

            # Extract just the numbers (remove commas)
            amount = amount_str.replace(',', '')
            if amount:
                try:
                    total_amount = float(amount)
                except ValueError:
                    pass
    return total_amount

